-- Shishi product v1.0 design DDL. Not a production migration.
PRAGMA foreign_keys=ON;
CREATE TABLE preference_versions(id TEXT PRIMARY KEY,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY,title TEXT NOT NULL,row_version INTEGER NOT NULL DEFAULT 1 CHECK(row_version>0),preference_id TEXT NOT NULL REFERENCES preference_versions(id),overrides_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'draft',deleted_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE assets(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,origin TEXT NOT NULL,storage_key TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL CHECK(length(sha256)=64),status TEXT NOT NULL,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE source_pages(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),asset_id TEXT REFERENCES assets(id),page_order INTEGER NOT NULL CHECK(page_order>=0),printed_page TEXT,ocr_json TEXT NOT NULL DEFAULT '{}',revision INTEGER NOT NULL DEFAULT 1,UNIQUE(project_id,page_order,revision));
CREATE TABLE source_spans(id TEXT PRIMARY KEY,page_id TEXT NOT NULL REFERENCES source_pages(id),text TEXT NOT NULL,bbox_json TEXT,revision INTEGER NOT NULL DEFAULT 1,granularity TEXT NOT NULL CHECK(granularity IN ('page','span')));
CREATE TABLE claims(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL CHECK(kind IN ('fact','author_view','creative','general')),status TEXT NOT NULL CHECK(status IN ('pending','verified','disputed','excluded')),statement TEXT NOT NULL);
CREATE TABLE claim_sources(claim_id TEXT NOT NULL REFERENCES claims(id),span_id TEXT NOT NULL REFERENCES source_spans(id),PRIMARY KEY(claim_id,span_id));
CREATE TABLE script_versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),parent_id TEXT REFERENCES script_versions(id),content_json TEXT NOT NULL,status TEXT NOT NULL,version_hash TEXT NOT NULL,CHECK(parent_id IS NULL OR parent_id<>id));
CREATE TABLE approvals(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),target_type TEXT NOT NULL CHECK(target_type IN ('script','timeline')),target_id TEXT NOT NULL,version_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,target_type,target_id,version_hash));
CREATE TABLE workflow_runs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),script_id TEXT REFERENCES script_versions(id),snapshot_json TEXT NOT NULL,status TEXT NOT NULL,reason_code TEXT,row_version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE jobs(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES workflow_runs(id),idempotency_key TEXT NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN ('queued','leased','submitting','submitted','running','unknown','cancel_requested','succeeded','failed','cancelled')),attempt INTEGER NOT NULL DEFAULT 1 CHECK(attempt>0),provider_task_id TEXT,input_hash TEXT NOT NULL,owner TEXT,lease_until TEXT,row_version INTEGER NOT NULL DEFAULT 1,result_json TEXT,created_at TEXT NOT NULL);
CREATE INDEX jobs_dispatch ON jobs(status,lease_until);
CREATE TABLE budget_entries(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),job_id TEXT REFERENCES jobs(id),kind TEXT NOT NULL CHECK(kind IN ('authorize','reserve','settle','release','adjust')),amount_micros INTEGER NOT NULL CHECK(amount_micros>=0),currency TEXT NOT NULL CHECK(currency IN ('CNY','USD')),entry_key TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE shots(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES workflow_runs(id),shot_key TEXT NOT NULL,payload_json TEXT NOT NULL,UNIQUE(run_id,shot_key));
CREATE TABLE dependency_edges(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),from_ref TEXT NOT NULL,to_ref TEXT NOT NULL,relation TEXT NOT NULL,CHECK(from_ref<>to_ref),UNIQUE(project_id,from_ref,to_ref,relation));
CREATE TABLE timeline_versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),parent_id TEXT REFERENCES timeline_versions(id),payload_json TEXT NOT NULL,status TEXT NOT NULL,version_hash TEXT NOT NULL,CHECK(parent_id IS NULL OR parent_id<>id));
CREATE TABLE feedback(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),target_id TEXT NOT NULL,text TEXT NOT NULL,plan_json TEXT,created_at TEXT NOT NULL);
CREATE TABLE exports(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),timeline_id TEXT NOT NULL REFERENCES timeline_versions(id),status TEXT NOT NULL,manifest_json TEXT,created_at TEXT NOT NULL);
CREATE TABLE project_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES projects(id),event_type TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE idempotency_records(scope TEXT NOT NULL,key TEXT NOT NULL,request_hash TEXT NOT NULL,response_json TEXT,created_at TEXT NOT NULL,PRIMARY KEY(scope,key));
